#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct{float x,y,z;} vec3; 
typedef struct{vec3 orig,dir;} ray;

typedef struct{vec3 p; vec3 n; float t; int hit;} hitrec;

static inline vec3 v(float x,float y,float z){vec3 r={x,y,z};return r;}
static inline vec3 vadd(vec3 a,vec3 b){return v(a.x+b.x,a.y+b.y,a.z+b.z);} 
static inline vec3 vsub(vec3 a,vec3 b){return v(a.x-b.x,a.y-b.y,a.z-b.z);} 
static inline vec3 vmul(vec3 a,float t){return v(a.x*t,a.y*t,a.z*t);} 
static inline float vdot(vec3 a,vec3 b){return a.x*b.x+a.y*b.y+a.z*b.z;} 
static inline float vlen(vec3 a){return sqrtf(vdot(a,a));}
static inline vec3 vunit(vec3 a){float l=vlen(a);return vmul(a,1.0f/l);} 

static ray ray_create(vec3 o, vec3 d){ray r={o,vunit(d)};return r;}
static vec3 ray_at(ray r,float t){return vadd(r.orig, vmul(r.dir,t));}

static hitrec sphere_intersect(vec3 center,float radius, ray r){
    hitrec h; h.hit=0; h.t=0; h.p=v(0,0,0); h.n=v(0,0,0);
    vec3 oc=vsub(r.orig, center);
    float a=vdot(r.dir,r.dir);
    float half_b=vdot(oc,r.dir);
    float c=vdot(oc,oc)-radius*radius;
    float disc=half_b*half_b - a*c;
    if(disc<0) return h;
    float sq=sqrtf(disc);
    float root=(-half_b - sq)/a;
    if(root<0.001f){root=(-half_b + sq)/a; if(root<0.001f) return h;}
    h.hit=1; h.t=root; h.p=ray_at(r,root); h.n=vmul(vsub(h.p,center),1.0f/radius);
    return h;
}

static hitrec plane_intersect(float y, ray r){
    hitrec h; h.hit=0; h.t=0; h.p=v(0,0,0); h.n=v(0,0,0);
    if(fabsf(r.dir.y) < 1e-6f) return h;
    float t=(y - r.orig.y)/r.dir.y;
    if(t<0.001f) return h;
    h.hit=1; h.t=t; h.p=ray_at(r,t); h.n=v(0,1,0);
    return h;
}

static vec3 sky_color(vec3 dir){
    float t=0.5f*(dir.y+1.0f);
    vec3 a=v(1,1,1);
    vec3 b=v(0.5f,0.7f,1.0f);
    return vadd(vmul(a,1.0f-t), vmul(b,t));
}

static int is_in_shadow(vec3 p, vec3 light){
    vec3 toL=vsub(light,p);
    float dist=vlen(toL);
    ray r=ray_create(p, toL);
    hitrec h=sphere_intersect(v(0,0.5f,-1.0f),0.5f,r);
    return h.hit && h.t<dist;
}

static vec3 trace(ray r, int depth){
    hitrec hs = sphere_intersect(v(0,0.5f,-1.0f),0.5f,r);
    hitrec hp = plane_intersect(0.0f,r);
    if(hs.hit && (!hp.hit || hs.t < hp.t)){
        vec3 light=v(-5.0f,-0.5f,0.0f);
        vec3 p=hs.p; vec3 n=hs.n;
        vec3 col=v(0.8f,0.1f,0.1f);
        vec3 ambient=vmul(col,0.2f);
        float diff=fmaxf(0.0f, vdot(n, vunit(vsub(light,p))));
        vec3 diffuse=vmul(col, diff);
        vec3 view=vunit(vmul(r.dir,-1.0f));
        vec3 halfv=vunit(vadd(vunit(vsub(light,p)), view));
        float spec=powf(fmaxf(0.0f, vdot(n, halfv)), 32.0f);
        vec3 specular=vmul(v(1,1,1), spec*0.5f);
        if(is_in_shadow(p, light)) diffuse=vmul(diffuse,0.2f);
        return vadd(ambient, vadd(diffuse,specular));
    }
    if(hp.hit){
        vec3 p=hp.p; int checker=((int)floorf(p.x)+(int)floorf(p.z))&1;
        vec3 c=checker? v(0.6f,0.6f,0.6f): v(0.26f,0.26f,0.26f);
        vec3 light=v(-5.0f,-0.5f,0.0f);
        float diff=fmaxf(0.0f, vdot(hp.n, vunit(vsub(light,p))));
        return vmul(c, diff);
    }
    return sky_color(r.dir);
}

int main(){
    const int W=800, H=600;
    fprintf(stderr,"Creating high-resolution image: %dx%d\n",W,H);
    fprintf(stderr,"This will be downsampled with ffmpeg after rendering\n");
    fprintf(stderr,"Rendering high-resolution image...\n");
    vec3 **img = malloc(sizeof(vec3*)*H);
    for(int y=0;y<H;y++) img[y]=malloc(sizeof(vec3)*W);
    vec3 origin=v(0,0,0);
    vec3 look=v(0,0,-1);
    vec3 dir=vunit(vsub(look,origin));
    float aspect=(float)W/(float)H;
    float viewport_h=2.0f;
    float viewport_w=aspect*viewport_h;
    float focal=1.0f;
    vec3 horizontal=v(viewport_w,0,0);
    vec3 vertical=v(0,viewport_h,0);
    vec3 lower_left=vsub(vsub(vsub(origin, vmul(horizontal,0.5f)), vmul(vertical,0.5f)), vmul(dir,focal));

    for(int j=0;j<H;j++){
        float progress = (100.0f*j)/ (float)H;
        fprintf(stderr,"Progress: %.1f%%\r",progress);
        for(int i=0;i<W;i++){
            float u=(float)i/(float)W;
            float v=(float)(H-1-j)/(float)H;
            vec3 pixel = vadd(lower_left, vadd(vmul(horizontal,u), vmul(vertical,v)));
            ray r=ray_create(origin, vsub(pixel, origin));
            img[j][i]=trace(r,0);
        }
    }
    fprintf(stderr,"Rendering complete\n");
    FILE *f=fopen("image.ppm","w");
    if(!f){fprintf(stderr,"Error: Could not open file %s for writing\n","image.ppm");return 1;}
    fprintf(f,"P3\n%d %d\n255\n",W,H);
    for(int y=0;y<H;y++){
        for(int x=0;x<W;x++){
            vec3 c=img[y][x];
            int ir=(int)(fminf(fmaxf(c.x,0.0f),1.0f)*255.99f);
            int ig=(int)(fminf(fmaxf(c.y,0.0f),1.0f)*255.99f);
            int ib=(int)(fminf(fmaxf(c.z,0.0f),1.0f)*255.99f);
            fprintf(f,"%d %d %d\n",ir,ig,ib);
        }
    }
    fclose(f);
    fprintf(stderr,"Wrote image to %s\n","image.ppm");
    fprintf(stderr,"Done.\n");
    for(int y=0;y<H;y++) free(img[y]);
    free(img);
    return 0;
}
